package vn.crossdock;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.util.*;import java.time.*;import static vn.crossdock.Db.*;
@Service public class Workflow {
 final Db db;final Settings settings;static final ZoneId Z=ZoneId.of("Asia/Ho_Chi_Minh");
 public Workflow(Db db,Settings settings){this.db=db;this.settings=settings;}
 public static final Set<String> KHO=Set.of("inspect","stage","unload","load","unloadBox","returnBox","reinspect");
 public static final Set<String> DP=Set.of("order","requirement","item","supply","inbound","lot","book","enter","leave","trip","allocate","unallocate","seal","unseal","depart","deliver","cancelOrder","cancelTrip","cancelVisit","consent");
 static String code(String prefix){return prefix+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();}
 static OffsetDateTime time(String v){try{return OffsetDateTime.parse(v);}catch(Exception e){return LocalDateTime.parse(v).atZone(Z).toOffsetDateTime();}}
 public long actor(String username){return n(db.one("select id from nguoi_dung where code=? and active",username),"id");}
 @Transactional public Object execute(String action,Map<String,Object> p,long actor){
 for(var e:p.entrySet())if(e.getValue()!=null&&(e.getKey().endsWith("_id")||e.getKey().equals("id")||e.getKey().equals("quantity"))){try{new java.math.BigDecimal(e.getValue().toString()).longValueExact();}catch(Exception ex){throw new IllegalArgumentException("ID và số lượng phải là số nguyên");}}
 db.lock();return switch(action){
 case "order"->createOrder(p,actor);case "requirement"->createRequirement(p);case "item"->createItem(p);
 case "supply"->supply(p,actor);case "inbound"->inbound(p,actor);case "lot"->lot(p);
 case "book"->book(p,actor);case "enter"->enter(n(p,"id"));case "leave"->leave(n(p,"id"));case "cancelVisit"->cancelVisit(n(p,"id"));
 case "inspect"->inspect(p,actor,false);case "reinspect"->inspect(p,actor,true);case "stage"->stage(p);case "unload"->unload(n(p,"id"));
 case "trip"->trip(p,actor);case "allocate"->allocate(p,actor);case "unallocate"->unallocate(p);case "seal"->seal(n(p,"id"));case "unseal"->unseal(n(p,"id"));
 case "load"->load(n(p,"id"),actor,true);case "unloadBox"->load(n(p,"id"),actor,false);case "depart"->depart(p,actor);
 case "deliver"->deliver(p,actor);case "returnBox"->returnBox(p,actor);case "cancelOrder"->cancelOrder(n(p,"id"));case "cancelTrip"->cancelTrip(n(p,"id"));
 case "consent"->{require(!s(p,"reason").isBlank(),"Cần ghi nhận sự đồng ý của khách hàng");db.run("update yeu_cau_giao set early_consent=? where id=?",s(p,"reason"),n(p,"id"));yield "Đã ghi nhận đồng ý giao sớm";}
 default->throw new IllegalArgumentException("Thao tác không hợp lệ");};}
 long createOrder(Map<String,Object>p,long actor){require((Boolean)db.get("khach_hang",n(p,"customer_id")).get("active"),"Khách hàng ngừng hoạt động");return db.insert("insert into don_hang(code,customer_id,created_by,note) values(?,?,?,?)",code("DH"),n(p,"customer_id"),actor,s(p,"note"));}
 long createRequirement(Map<String,Object>p){var o=db.get("don_hang",n(p,"order_id"));var l=db.get("dia_diem_giao",n(p,"location_id"));require("OPEN".equals(s(o,"status")),"Đơn hàng không còn mở");require(n(o,"customer_id")==n(l,"customer_id")&&(Boolean)l.get("active"),"Địa điểm phải thuộc khách hàng của đơn");return db.insert("insert into yeu_cau_giao(code,order_id,location_id,earliest,latest) values(?,?,?,?,?)",code("YC"),n(p,"order_id"),n(p,"location_id"),LocalDate.parse(s(p,"earliest")),LocalDate.parse(s(p,"latest")));}
 long createItem(Map<String,Object>p){var r=db.get("yeu_cau_giao",n(p,"requirement_id"));require("OPEN".equals(s(r,"status")),"Yêu cầu đã bắt đầu phân bổ");require(db.count("select count(*) from thung_hang b join chi_tiet_yeu_cau d on d.id=b.detail_id where d.requirement_id=?",n(r,"id"))==0,"Đã có hàng: không thêm linh kiện làm thay đổi yêu cầu");require((Boolean)db.get("linh_kien",n(p,"part_id")).get("active"),"Linh kiện ngừng sử dụng");return db.insert("insert into chi_tiet_yeu_cau(requirement_id,part_id,quantity) values(?,?,?)",n(p,"requirement_id"),n(p,"part_id"),n(p,"quantity"));}
 long supply(Map<String,Object>p,long actor){var d=db.get("chi_tiet_yeu_cau",n(p,"detail_id"));require("OPEN".equals(s(db.get("yeu_cau_giao",n(d,"requirement_id")),"status")),"Yêu cầu không còn mở");require((Boolean)db.get("nha_cung_cap",n(p,"supplier_id")).get("active"),"Nhà cung cấp ngừng hoạt động");return db.insert("insert into xac_nhan_cung_cap(supplier_id,detail_id,quantity,promised_date,status,note,created_by) values(?,?,?,?,?,?,?)",n(p,"supplier_id"),n(p,"detail_id"),n(p,"quantity"),LocalDate.parse(s(p,"promised_date")),s(p,"status"),s(p,"note"),actor);}
 long inbound(Map<String,Object>p,long actor){require((Boolean)db.get("xe",n(p,"vehicle_id")).get("active"),"Xe ngừng sử dụng");return db.insert("insert into chuyen_nhap(code,vehicle_id,planned_at,created_by,note) values(?,?,?,?,?)",code("CN"),n(p,"vehicle_id"),time(s(p,"planned_at")),actor,s(p,"note"));}
 long lot(Map<String,Object>p){require("EXPECTED".equals(s(db.get("chuyen_nhap",n(p,"inbound_id")),"status")),"Chuyến đã vào kho");return db.insert("insert into lo_nhap(code,inbound_id,supplier_id) values(?,?,?)",code("LO"),n(p,"inbound_id"),n(p,"supplier_id"));}
 long book(Map<String,Object>p,long actor){var gate=db.get("cong_kho",n(p,"gate_id"));boolean in="IN".equals(s(gate,"kind"));long id=n(p,in?"inbound_id":"outbound_id");var t=db.get(in?"chuyen_nhap":"chuyen_xuat",id);require((Boolean)gate.get("active"),"Cổng ngừng sử dụng");require(in?"EXPECTED".equals(s(t,"status")):"READY".equals(s(t,"status")),"Chuyến chưa đủ điều kiện đặt cổng");OffsetDateTime start=time(s(p,"planned_start")),end=time(s(p,"planned_end"));require(end.isAfter(start),"Giờ kết thúc phải sau bắt đầu");
 require(db.count("select count(*) from luot_phuc_vu where gate_id=? and status in ('WAITING','IN_GATE') and planned_start<? and planned_end>?",n(gate,"id"),end,start)==0,"Cổng trùng lịch: chọn khung giờ tiếp theo");
 require(db.count("select count(*) from luot_phuc_vu v left join chuyen_nhap i on i.id=v.inbound_id left join chuyen_xuat o on o.id=v.outbound_id where v.status in ('WAITING','IN_GATE') and coalesce(i.vehicle_id,o.vehicle_id)=? and v.planned_start<? and v.planned_end>?",n(t,"vehicle_id"),end,start)==0,"Xe trùng lịch phục vụ");
 require(db.count("select count(*) from luot_phuc_vu where "+(in?"inbound_id":"outbound_id")+"=? and status in ('WAITING','IN_GATE')",id)==0,"Chuyến đã có lượt chờ hoặc đang ở cổng");
 return db.insert("insert into luot_phuc_vu(gate_id,inbound_id,outbound_id,planned_start,planned_end,created_by) values(?,?,?,?,?,?)",n(gate,"id"),in?id:null,in?null:id,start,end,actor);}
 String enter(long id){var v=db.get("luot_phuc_vu",id);require("WAITING".equals(s(v,"status")),"Lượt không còn chờ");require((Boolean)db.get("cong_kho",n(v,"gate_id")).get("active"),"Cổng ngừng hoạt động");require(db.count("select count(*) from luot_phuc_vu where gate_id=? and status='IN_GATE'",n(v,"gate_id"))==0,"Cổng đang bận; xe phải chờ");boolean in=n(v,"inbound_id")>0;var t=db.get(in?"chuyen_nhap":"chuyen_xuat",n(v,in?"inbound_id":"outbound_id"));require(in?"EXPECTED".equals(s(t,"status")):"READY".equals(s(t,"status")),"Trạng thái chuyến đã thay đổi");
 require(db.count("select count(*) from luot_phuc_vu v left join chuyen_nhap i on i.id=v.inbound_id left join chuyen_xuat o on o.id=v.outbound_id where v.status='IN_GATE' and coalesce(i.vehicle_id,o.vehicle_id)=?",n(t,"vehicle_id"))==0,"Xe đang phục vụ ở cổng khác");
 require(db.count("select count(*) from chuyen_xuat where vehicle_id=? and status='SHIPPED'",n(t,"vehicle_id"))==0,"Xe còn chuyến đang giao");db.run("update luot_phuc_vu set status='IN_GATE',arrived_at=now() where id=?",id);if(in)db.run("update chuyen_nhap set status='RECEIVING' where id=?",n(t,"id"));return "Xe đã vào cổng";}
 String leave(long id){var v=db.get("luot_phuc_vu",id);require(n(v,"inbound_id")>0&&"IN_GATE".equals(s(v,"status")),"Chỉ xác nhận xe nhập đang ở cổng");require("UNLOADED".equals(s(db.get("chuyen_nhap",n(v,"inbound_id")),"status")),"Kho chưa xác nhận dỡ xong");db.run("update luot_phuc_vu set status='DONE',left_at=now() where id=?",id);db.run("update chuyen_nhap set status='LEFT' where id=?",n(v,"inbound_id"));return "Đã giải phóng cổng nhập";}
 String cancelVisit(long id){require("WAITING".equals(s(db.get("luot_phuc_vu",id),"status")),"Chỉ hủy lượt chưa vào cổng");db.run("update luot_phuc_vu set status='CANCELLED' where id=?",id);return "Đã hủy lượt chờ";}
 String inspect(Map<String,Object>p,long actor,boolean re){long id=n(p,"id");var b=db.get("thung_hang",id);require((re?Set.of("QUARANTINE","RETURNED"):Set.of("EXPECTED")).contains(s(b,"status")),"Thùng không ở bước kiểm nhận");if(!re)require(db.count("select count(*) from lo_nhap l join luot_phuc_vu v on v.inbound_id=l.inbound_id where l.id=? and v.status='IN_GATE'",n(b,"lot_id"))>0,"Xe chưa vào cổng nhập");boolean pass="ACCEPTED".equals(s(p,"result"));require(pass||!s(p,"note").isBlank(),"Cần ghi lý do cách ly");long qty=n(p,"quantity");require(qty>0&&d(p,"gross_kg")>0&&d(p,"gross_kg")<=18000,"Số lượng và kg thực tế phải dương, mỗi thùng không quá 18 tấn");if(pass){long wanted=n(db.get("chi_tiet_yeu_cau",n(b,"detail_id")),"quantity");long have=db.count("select coalesce(sum(quantity),0) from thung_hang where detail_id=? and id<>? and status not in ('EXPECTED','QUARANTINE','RETURNED')",n(b,"detail_id"),id);require(have+qty<=wanted,"Số lượng đạt vượt yêu cầu giao; cách ly phần bất thường, không tách thùng");}
 db.run("update thung_hang set quantity=?,gross_kg=?,status=?,inspected_by=?,inspected_at=now(),note=?,staging_id=null where id=?",qty,d(p,"gross_kg"),pass?"ACCEPTED":"QUARANTINE",actor,s(p,"note"),id);return pass?"Đã kiểm nhận đạt; chờ phân loại":"Đã cách ly thùng";}
 String stage(Map<String,Object>p){var b=db.get("thung_hang",n(p,"id"));require(Set.of("ACCEPTED","STAGED").contains(s(b,"status")),"Thùng chưa đạt hoặc đã phân bổ");var k=db.get("khu_cho",n(p,"staging_id"));String region=s(db.one("select l.region from chi_tiet_yeu_cau d join yeu_cau_giao r on r.id=d.requirement_id join dia_diem_giao l on l.id=r.location_id where d.id=?",n(b,"detail_id")),"region");require((Boolean)k.get("active")&&region.equals(s(k,"region")),"Khu chờ phải đúng miền và đang hoạt động");require(db.count("select count(*) from thung_hang where staging_id=? and id<>?",n(k,"id"),n(b,"id"))<n(k,"capacity"),"Khu chờ đã đầy");String label=s(b,"code").startsWith(region+"-")?s(b,"code"):code(region);db.run("update thung_hang set code=?,status='STAGED',staging_id=?,staged_at=now() where id=?",label,n(k,"id"),n(b,"id"));return "Đã bố trí khu chờ; điều phối sẽ thấy tiến độ mới";}
 String unload(long id){require("RECEIVING".equals(s(db.get("chuyen_nhap",id),"status")),"Chuyến chưa nhận hàng");require(db.count("select count(*) from thung_hang b join lo_nhap l on l.id=b.lot_id where l.inbound_id=?",id)>0,"Chuyến chưa có thùng");require(db.count("select count(*) from thung_hang b join lo_nhap l on l.id=b.lot_id where l.inbound_id=? and b.status='EXPECTED'",id)==0,"Còn thùng chưa kiểm nhận");db.run("update chuyen_nhap set status='UNLOADED',unloaded_at=now() where id=?",id);return "Đã dỡ xong; chờ điều phối xác nhận xe rời cổng";}
 long trip(Map<String,Object>p,long actor){var x=db.get("xe",n(p,"vehicle_id"));require((Boolean)x.get("active")&&s(x,"region").equals(s(p,"region")),"Xe không đúng miền hoặc ngừng sử dụng");require(!s(p,"driver").isBlank(),"Nhập tên tài xế");return db.insert("insert into chuyen_xuat(code,vehicle_id,region,driver,planned_at,created_by) values(?,?,?,?,?,?)",code("CX-"+s(p,"region")),n(p,"vehicle_id"),s(p,"region"),s(p,"driver"),time(s(p,"planned_at")),actor);}
 public boolean sufficient(long req){return db.count("select count(*) from chi_tiet_yeu_cau where requirement_id=?",req)>0&&db.count("select count(*) from chi_tiet_yeu_cau d where d.requirement_id=? and d.quantity<>coalesce((select sum(b.quantity) from thung_hang b where b.detail_id=d.id and b.status in ('STAGED','ALLOCATED','LOADED','SHIPPED','DELIVERED')),0)",req)==0;}
 public double weight(long trip){return d(db.one("select coalesce(sum(b.gross_kg),0) as kg from phan_bo_thung a join thung_hang b on b.id=a.box_id join diem_giao_chuyen s on s.id=a.stop_id where s.trip_id=? and a.status<>'CANCELLED'",trip),"kg");}
 String allocate(Map<String,Object>p,long actor){long tid=n(p,"trip_id"),rid=n(p,"requirement_id");var t=db.get("chuyen_xuat",tid);var r=db.get("yeu_cau_giao",rid);var loc=db.get("dia_diem_giao",n(r,"location_id"));require("DRAFT".equals(s(t,"status")),"Chỉ phân bổ chuyến nháp");require(Set.of("OPEN","ALLOCATED").contains(s(r,"status")),"Yêu cầu không còn được phân bổ");require(s(t,"region").equals(s(loc,"region")),"Không ghép khác miền");require(sufficient(rid),"Chưa đủ từng loại linh kiện đạt và đã vào khu chờ");
 double total=d(db.one("select sum(b.gross_kg) as kg from thung_hang b join chi_tiet_yeu_cau d on d.id=b.detail_id where d.requirement_id=? and b.status in ('STAGED','ALLOCATED','LOADED','SHIPPED','DELIVERED')",rid),"kg");
 double cap=d(db.get("xe",n(t,"vehicle_id")),"capacity_kg");var boxes=db.rows("select b.* from thung_hang b join chi_tiet_yeu_cau d on d.id=b.detail_id where d.requirement_id=? and b.status='STAGED' order by b.id",rid);require(!boxes.isEmpty(),"Không còn thùng sẵn sàng");
 boolean retry=db.count("select count(*) from phan_bo_thung a join thung_hang b on b.id=a.box_id join chi_tiet_yeu_cau d on d.id=b.detail_id where d.requirement_id=? and a.status='RETURNED'",rid)>0;
 boolean oversized=total>18000||retry;List<Map<String,Object>>chosen=new ArrayList<>();double sum=0;
 if(oversized){require(weight(tid)==0,"Yêu cầu trên 18 tấn hoặc hàng giao lại phải đi chuyến riêng");for(var b:boxes){if(sum+d(b,"gross_kg")<=cap+0.0000001){chosen.add(b);sum+=d(b,"gross_kg");}}require(!chosen.isEmpty(),"Không thùng nguyên nào vừa tải trọng xe");}
 else {require(db.count("select count(*) from phan_bo_thung a join diem_giao_chuyen s on s.id=a.stop_id join thung_hang b on b.id=a.box_id join chi_tiet_yeu_cau d on d.id=b.detail_id where s.trip_id=? and a.status<>'CANCELLED' and exists(select 1 from phan_bo_thung old join thung_hang ob on ob.id=old.box_id join chi_tiet_yeu_cau od on od.id=ob.detail_id where old.status='RETURNED' and od.requirement_id=d.requirement_id)",tid)==0,"Không ghép khách khác vào chuyến giao lại hàng hoàn");require(boxes.stream().mapToDouble(b->d(b,"gross_kg")).sum()==total,"Không lấy nửa yêu cầu đã gán chuyến khác");require(db.count("select count(*) from phan_bo_thung a join diem_giao_chuyen s on s.id=a.stop_id join thung_hang b on b.id=a.box_id join chi_tiet_yeu_cau d on d.id=b.detail_id where s.trip_id=? and a.status<>'CANCELLED' and (select sum(b2.gross_kg) from thung_hang b2 join chi_tiet_yeu_cau d2 on d2.id=b2.detail_id where d2.requirement_id=d.requirement_id and b2.status not in ('EXPECTED','QUARANTINE','RETURNED'))>18000",tid)==0,"Không ghép vào chuyến riêng của yêu cầu quá tải");chosen.addAll(boxes);sum=total;require(weight(tid)+sum<=cap+0.0000001,"Ghép nguyên yêu cầu sẽ vượt tải trọng xe");}
 var stops=db.rows("select * from diem_giao_chuyen where trip_id=? and location_id=?",tid,n(loc,"id"));long sid=stops.isEmpty()?db.insert("insert into diem_giao_chuyen(trip_id,location_id,sequence_no,address_snapshot) values(?,?,?,?)",tid,n(loc,"id"),db.count("select coalesce(max(sequence_no),0)+1 from diem_giao_chuyen where trip_id=?",tid),s(loc,"address")):n(stops.getFirst(),"id");
 for(var b:chosen){db.insert("insert into phan_bo_thung(box_id,stop_id,allocated_by) values(?,?,?)",n(b,"id"),sid,actor);db.run("update thung_hang set status='ALLOCATED' where id=?",n(b,"id"));}db.run("update yeu_cau_giao set status='ALLOCATED' where id=?",rid);return "Đã phân bổ "+chosen.size()+" thùng nguyên • "+sum+" kg";}
 String unallocate(Map<String,Object>p){long tid=n(p,"trip_id"),rid=n(p,"requirement_id");require("DRAFT".equals(s(db.get("chuyen_xuat",tid),"status")),"Chỉ bỏ phân bổ ở chuyến nháp");var allocations=db.rows("select a.* from phan_bo_thung a join diem_giao_chuyen s on s.id=a.stop_id join thung_hang b on b.id=a.box_id join chi_tiet_yeu_cau d on d.id=b.detail_id where s.trip_id=? and d.requirement_id=? and a.status='ALLOCATED'",tid,rid);for(var a:allocations){db.run("update phan_bo_thung set status='CANCELLED' where id=?",n(a,"id"));db.run("update thung_hang set status='STAGED' where id=?",n(a,"box_id"));}refreshRequirement(rid);return "Đã bỏ phân bổ toàn bộ phần yêu cầu trên chuyến";}
 String seal(long id){require("DRAFT".equals(s(db.get("chuyen_xuat",id),"status")),"Chuyến không ở trạng thái nháp");require(weight(id)>0,"Chuyến chưa có hàng");db.run("update chuyen_xuat set status='READY' where id=?",id);return "Đã chốt chuyến; đặt cổng và cho xe vào để kho xếp hàng";}
 String unseal(long id){require("READY".equals(s(db.get("chuyen_xuat",id),"status")),"Chỉ mở lại chuyến đã chốt");require(db.count("select count(*) from luot_phuc_vu where outbound_id=? and status in ('WAITING','IN_GATE')",id)==0,"Hủy lượt cổng trước khi mở lại");db.run("update chuyen_xuat set status='DRAFT' where id=?",id);return "Đã mở lại chuyến";}
 String load(long id,long actor,boolean on){var a=db.get("phan_bo_thung",id);var stop=db.get("diem_giao_chuyen",n(a,"stop_id"));long tid=n(stop,"trip_id");require("READY".equals(s(db.get("chuyen_xuat",tid),"status")),"Chuyến chưa chốt hoặc đã xuất");require(db.count("select count(*) from luot_phuc_vu where outbound_id=? and status='IN_GATE'",tid)==1,"Xe chưa ở cổng xuất");require((on?"ALLOCATED":"LOADED").equals(s(a,"status")),"Thùng không ở bước xếp/dỡ tương ứng");db.run("update phan_bo_thung set status=?,loaded_by=?,loaded_at="+(on?"now()":"null")+" where id=?",on?"LOADED":"ALLOCATED",on?actor:null,id);db.run("update thung_hang set status=? where id=?",on?"LOADED":"ALLOCATED",n(a,"box_id"));return on?"Đã xếp thùng; cập nhật công việc điều phối":"Đã dỡ thùng khỏi xe";}
 String depart(Map<String,Object>p,long actor){long id=n(p,"id");var t=db.get("chuyen_xuat",id);require("READY".equals(s(t,"status")),"Chuyến chưa chốt hoặc đã xuất");require(db.count("select count(*) from luot_phuc_vu where outbound_id=? and status='IN_GATE'",id)==1,"Xe chưa ở cổng xuất");require(weight(id)>0&&db.count("select count(*) from phan_bo_thung a join diem_giao_chuyen s on s.id=a.stop_id where s.trip_id=? and a.status not in ('LOADED','CANCELLED')",id)==0,"Kho chưa xếp đủ hàng");double cap=d(db.get("xe",n(t,"vehicle_id")),"capacity_kg");require(weight(id)<=cap+0.0000001&&weight(id)<=18000.0000001,"Chuyến vượt tải trọng");require(weight(id)/cap*100>=settings.get("minLoadPercent")||!s(p,"reason").isBlank(),"Chuyến dưới mức gom hàng; cần nhập lý do xuất");
 db.run("update chuyen_xuat set status='SHIPPED',dispatched_at=now(),dispatched_by=?,underload_reason=? where id=?",actor,s(p,"reason"),id);
 db.run("update thung_hang set status='SHIPPED',staging_id=null where id in (select a.box_id from phan_bo_thung a join diem_giao_chuyen s on s.id=a.stop_id where s.trip_id=? and a.status='LOADED')",id);db.run("update phan_bo_thung set status='SHIPPED' where stop_id in (select id from diem_giao_chuyen where trip_id=?) and status='LOADED'",id);db.run("update luot_phuc_vu set status='DONE',left_at=now() where outbound_id=? and status='IN_GATE'",id);return "Đã xuất kho, giải phóng cổng và khu chờ. Có thể in PDF.";}
 String deliver(Map<String,Object>p,long actor){long aid=n(p,"allocation_id");var a=db.get("phan_bo_thung",aid);require("SHIPPED".equals(s(a,"status")),"Thùng đã giao/đang chờ hoàn hoặc chưa xuất");var stop=db.get("diem_giao_chuyen",n(a,"stop_id"));var trip=db.get("chuyen_xuat",n(stop,"trip_id"));var r=db.one("select r.* from yeu_cau_giao r join chi_tiet_yeu_cau d on d.requirement_id=r.id join thung_hang b on b.detail_id=d.id where b.id=?",n(a,"box_id"));OffsetDateTime at=time(s(p,"delivered_at"));OffsetDateTime dispatched=((java.sql.Timestamp)trip.get("dispatched_at")).toInstant().atOffset(ZoneOffset.UTC);require(!at.isBefore(dispatched)&&!at.isAfter(OffsetDateTime.now().plusMinutes(2)),"Thời điểm giao phải từ lúc xuất đến hiện tại");String status=s(p,"status");require(Set.of("DELIVERED","FAILED","RETURN_PENDING").contains(status),"Kết quả giao không hợp lệ");LocalDate day=at.atZoneSameInstant(Z).toLocalDate();require(!status.equals("DELIVERED")||!day.isBefore(((java.sql.Date)r.get("earliest")).toLocalDate())||!s(r,"early_consent").isBlank(),"Giao trước khung ngày: phải ghi nhận khách hàng đồng ý");require(status.equals("DELIVERED")||!s(p,"note").isBlank(),"Thất bại/hoàn phải có lý do");int days=s(trip,"region").equals("MB")?5:s(trip,"region").equals("MT")?3:settings.get("southDays");boolean late=day.isAfter(((java.sql.Date)r.get("latest")).toLocalDate())||at.isAfter(dispatched.plusDays(days));long result=db.insert("insert into ket_qua_giao_hang(stop_id,delivered_at,recorded_by,note) values(?,?,?,?)",n(stop,"id"),at,actor,s(p,"note"));db.insert("insert into chi_tiet_giao(result_id,allocation_id,status,late,note) values(?,?,?,?,?)",result,aid,status,late,s(p,"note"));
 if(!status.equals("FAILED")){db.run("update phan_bo_thung set status=? where id=?",status,aid);db.run("update thung_hang set status=? where id=?",status,n(a,"box_id"));}refreshStop(n(stop,"id"));refreshRequirement(n(r,"id"));return late?"Đã ghi nhận kết quả thực tế • Giao trễ":"Đã ghi nhận kết quả từng thùng";}
 String returnBox(Map<String,Object>p,long actor){var b=db.get("thung_hang",n(p,"id"));require("RETURN_PENDING".equals(s(b,"status")),"Chưa có yêu cầu hoàn");require(!s(p,"note").isBlank(),"Ghi tình trạng hàng thực tế khi nhận lại");var a=db.one("select * from phan_bo_thung where box_id=? and status='RETURN_PENDING'",n(b,"id"));db.run("update phan_bo_thung set status='RETURNED' where id=?",n(a,"id"));db.run("update thung_hang set status='RETURNED',staging_id=null,inspected_by=?,inspected_at=now(),note=? where id=?",actor,s(p,"note"),n(b,"id"));refreshStop(n(a,"stop_id"));var detail=db.get("chi_tiet_yeu_cau",n(b,"detail_id"));refreshRequirement(n(detail,"requirement_id"));return "Đã nhận hoàn thực tế; kiểm tra lại trước khi đưa vào khu chờ";}
 void refreshStop(long sid){long pending=db.count("select count(*) from phan_bo_thung where stop_id=? and status in ('SHIPPED','RETURN_PENDING')",sid);long delivered=db.count("select count(*) from phan_bo_thung where stop_id=? and status='DELIVERED'",sid);long returned=db.count("select count(*) from phan_bo_thung where stop_id=? and status='RETURNED'",sid);db.run("update diem_giao_chuyen set status=? where id=?",pending==0?(returned>0?"CLOSED_RETURN":"DONE"):(delivered>0?"PARTIAL":"PENDING"),sid);long tid=n(db.get("diem_giao_chuyen",sid),"trip_id");if(db.count("select count(*) from phan_bo_thung a join diem_giao_chuyen s on s.id=a.stop_id where s.trip_id=? and a.status in ('SHIPPED','RETURN_PENDING')",tid)==0)db.run("update chuyen_xuat set status='DONE' where id=?",tid);}
 void refreshRequirement(long rid){boolean done=db.count("select count(*) from chi_tiet_yeu_cau d where requirement_id=? and quantity<>coalesce((select sum(quantity) from thung_hang b where b.detail_id=d.id and b.status='DELIVERED'),0)",rid)==0;boolean allocated=db.count("select count(*) from thung_hang b join chi_tiet_yeu_cau d on d.id=b.detail_id where d.requirement_id=? and b.status in ('ALLOCATED','LOADED','SHIPPED','RETURN_PENDING','DELIVERED')",rid)>0;db.run("update yeu_cau_giao set status=? where id=?",done?"DONE":allocated?"ALLOCATED":"OPEN",rid);long oid=n(db.get("yeu_cau_giao",rid),"order_id");if(db.count("select count(*) from yeu_cau_giao where order_id=? and status not in ('DONE','CANCELLED')",oid)==0)db.run("update don_hang set status='DONE' where id=?",oid);}
 String cancelOrder(long id){require("OPEN".equals(s(db.get("don_hang",id),"status")),"Đơn không còn mở");require(db.count("select count(*) from thung_hang b join chi_tiet_yeu_cau d on d.id=b.detail_id join yeu_cau_giao r on r.id=d.requirement_id where r.order_id=?",id)==0,"Đã có hàng, không được hủy đơn");db.run("update yeu_cau_giao set status='CANCELLED' where order_id=?",id);db.run("update don_hang set status='CANCELLED' where id=?",id);return "Đã hủy đơn";}
 String cancelTrip(long id){require("DRAFT".equals(s(db.get("chuyen_xuat",id),"status"))&&weight(id)==0,"Chỉ hủy chuyến nháp đã bỏ hết phân bổ");db.run("update chuyen_xuat set status='CANCELLED' where id=?",id);return "Đã hủy chuyến";}
}
